template <class traits, class charT, class ST = std::char_traits<charT>, class SA = std::allocator<charT>>
basic_string<charT> regex_replace(
    const charT* s,
    const basic_regex<charT, traits>& e,
    const basic_string<charT, ST, SA>& fmt,
    regex_constants::match_flag_type flags = regex_constants::match_default);

code_example:
#include <iostream>
#include <string>
#include <regex>

int main() {
    std::string text = "The quick brown fox jumps over the lazy dog.";
    std::regex vowel_regex("[aeiou]");
    std::string replacement = "*";
    // Using regex_replace with default flags
    std::string result = std::regex_replace(text, vowel_regex, replacement);
    std::cout << result << std::endl;
    return 0;
}
